const items = $input.all();

function readField(root, aliases) {
  const aliasSet = new Set(aliases.map((v) => String(v).toLowerCase()));

  for (const alias of aliases) {
    if (root?.[alias] !== undefined && root?.[alias] !== null && root?.[alias] !== '') {
      return root[alias];
    }
  }

  const fields = root?.fields;
  if (Array.isArray(fields)) {
    for (const field of fields) {
      const candidates = [field?.key, field?.label, field?.name, field?.title]
        .filter(Boolean)
        .map((v) => String(v).toLowerCase());
      if (candidates.some((candidate) => aliasSet.has(candidate))) {
        if (field?.value !== undefined) return field.value;
        if (field?.answer?.value !== undefined) return field.answer.value;
        if (field?.answer !== undefined) return field.answer;
      }
    }
  }

  return '';
}

return items.map((item) => {
  const incoming = item.json?.data ?? item.json;
  const responseId = incoming?.responseId ?? incoming?.submissionId ?? item.json?.id ?? `resp-${Date.now()}`;
  const name = String(readField(incoming, ['name', 'customer_name', '이름'])).trim();
  const product = String(readField(incoming, ['product', 'service', '상품', '서비스'])).trim();
  const theme = String(readField(incoming, ['theme', 'mood', '분위기', '컨셉'])).trim();
  const extraPrompt = String(readField(incoming, ['extra_prompt', 'prompt', '추가 요청', '요청사항'])).trim();
  const phone = String(readField(incoming, ['phone', 'mobile', '전화번호'])).replace(/\D/g, '');

  const config = {
    baseBioPrompt: $env.BASE_BIO_PROMPT || '브랜드 톤: premium, warm, modern',
    geminiApiKey: $env.GEMINI_API_KEY || '',
    cloudinaryCloudName: $env.CLOUDINARY_CLOUD_NAME || '',
    cloudinaryUploadPreset: $env.CLOUDINARY_UPLOAD_PRESET || '',
    cloudinaryFolder: $env.CLOUDINARY_FOLDER || 'tally-gemini-kakao',
    kakaoRestApiKey: $env.KAKAO_REST_API_KEY || '',
    kakaoClientSecret: $env.KAKAO_CLIENT_SECRET || '',
    kakaoRefreshToken: $env.KAKAO_REFRESH_TOKEN || '',
    resultLinkBaseUrl: $env.RESULT_LINK_BASE_URL || '',
    kakaoMessageTitle: $env.KAKAO_MESSAGE_TITLE || '맞춤 이미지가 생성되었습니다',
    kakaoMessageDescription: $env.KAKAO_MESSAGE_DESCRIPTION || 'Tally 제출 결과를 확인해보세요.'
  };

  const missing = Object.entries({
    GEMINI_API_KEY: config.geminiApiKey,
    CLOUDINARY_CLOUD_NAME: config.cloudinaryCloudName,
    CLOUDINARY_UPLOAD_PRESET: config.cloudinaryUploadPreset,
    KAKAO_REST_API_KEY: config.kakaoRestApiKey,
    KAKAO_REFRESH_TOKEN: config.kakaoRefreshToken
  }).filter(([, value]) => !value).map(([key]) => key);

  if (missing.length) {
    throw new Error(`Missing required environment variables: ${missing.join(', ')}`);
  }

  const prompt = [
    config.baseBioPrompt,
    `고객명: ${name || '미입력'}`,
    `상품/서비스: ${product || '미입력'}`,
    `희망 분위기: ${theme || '미입력'}`,
    `추가 요청: ${extraPrompt || '없음'}`,
    '텍스트 오버레이 없이, 4:3 비율, 광고 크리에이티브 느낌, 선명한 디테일, 카카오톡 공유에 적합한 800x600 구도'
  ].join('\n');

  return {
    json: {
      responseId,
      name,
      phone,
      product,
      theme,
      extraPrompt,
      prompt,
      ...config
    }
  };
});

const items = $input.all();

return items.map((item) => {
  const original = item.json;
  const parts = original?.candidates?.[0]?.content?.parts ?? [];
  const imagePart = parts.find((part) => part?.inlineData?.data);
  const textPart = parts.find((part) => part?.text);

  if (!imagePart) {
    throw new Error('Gemini response did not include inline image data.');
  }

  const previous = $items('Prepare Input', 0, item.pairedItem?.item ?? 0)?.[0]?.json ?? {};

  return {
    json: {
      ...previous,
      modelText: textPart?.text || ''
    },
    binary: {
      image: {
        data: imagePart.inlineData.data,
        mimeType: imagePart.inlineData.mimeType || 'image/png',
        fileName: `${previous.responseId || 'generated'}-image`
      }
    },
    pairedItem: item.pairedItem
  };
});

const uploads = $items('Upload To Cloudinary');
const tokens = $input.all();

return tokens.map((tokenItem, index) => {
  const tokenJson = tokenItem.json;
  const source = uploads[index]?.json ?? {};
  const prepared = $items('Prepare Input', 0, index)?.[0]?.json ?? {};

  if (!source.secure_url) {
    throw new Error('Cloudinary upload did not return secure_url.');
  }

  const resultUrl = prepared.resultLinkBaseUrl
    ? `${prepared.resultLinkBaseUrl.replace(/\/$/, '')}/${prepared.responseId}`
    : source.secure_url;

  const templateObject = {
    object_type: 'feed',
    content: {
      title: prepared.kakaoMessageTitle,
      description: prepared.kakaoMessageDescription,
      image_url: source.secure_url,
      image_width: 800,
      image_height: 600,
      link: {
        web_url: resultUrl,
        mobile_web_url: resultUrl
      }
    },
    buttons: [
      {
        title: '이미지 보기',
        link: {
          web_url: resultUrl,
          mobile_web_url: resultUrl
        }
      }
    ]
  };

  return {
    json: {
      ...prepared,
      uploadedImageUrl: source.secure_url,
      resultUrl,
      kakaoAccessToken: tokenJson.access_token,
      kakaoTemplateObject: JSON.stringify(templateObject)
    }
  };
});
